import React from 'react';
import { useParams } from 'react-router-dom';
import './SubForumDetail.css';

const SubForumDetail = ({ subForums }) => {
    const { id } = useParams();
    const subForum = subForums.find(subForum => subForum.id === parseInt(id));

    if (!subForum) {
        return <p>SubForum not found</p>;
    }

    return (
        <div className="subforum-detail">
            <h2>{subForum.name}</h2>
            <p>{subForum.description}</p>
            <div className="threads">
                <h3>Threads</h3>
                {subForum.threads.length > 0 ? (
                    <ul>
                        {subForum.threads.map(thread => (
                            <li key={thread.id}>
                                <h4>
                                    <Link to={`/thread/${thread.id}`}>{thread.title}</Link>
                                </h4>
                                <p><em>by {thread.author} on {thread.date}</em></p>
                            </li>
                        ))}
                    </ul>
                ) : (
                    <p>No threads available</p>
                )}
            </div>
        </div>
    );
};

export default SubForumDetail;
